{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C11"],
      "claim": "Vonoprazan, the closest structural analogue (Morgan 0.3803), has an estimated human oral bioavailability of 36%, which is above the 20% threshold; this directly supports a high-F prediction for the query, which shares the methylaminomethyl, N-sulfonyl aryl, and substituted aryl pyrrole core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Dolutegravir shows approximately 70% oral bioavailability in healthy volunteers, providing supportive but weakly transferable evidence that complex heteroaromatic drugs can achieve high oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Safinamide has a high absolute oral bioavailability of 95% in humans, demonstrating that moderate-size, ionizable oral drugs can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Genaconazole, which contains a difluorophenyl group and an azole heterocycle, showed 100% absolute oral bioavailability in healthy volunteers, supporting high F for the query's difluorophenyl-containing scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Sulfadoxine, a sulfonamide-containing drug, has >90% oral bioavailability in healthy adults, supporting that the sulfonyl group in the query is not an inherent barrier to high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue vonoprazan has human F=36%, above the 20% threshold, and all other transferable experimental evidence reports F values of 50-100%; no evidence supports F<20%. The physicochemical prior is favorable. Therefore predict high oral bioavailability (F>=20%) with moderate confidence.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule.",
    "Vonoprazan F=36% was estimated from PBPK-PD modeling rather than a dedicated IV-comparison absolute bioavailability study.",
    "Morgan similarities to most evidence molecules are low, limiting transferability.",
    "Metabolic stability and transporter/efflux behavior of the query are not experimentally characterized."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

